from scapy.all import IP, TCP

# Las IP del propio cortafuegos: una hacia la LAN y otra hacia fuera
MIS_IP = {"192.168.1.1", "203.0.113.1"}

def cadena(p):
    # La pregunta clave: ¿el paquete es para mí, sale de mí o pasa?
    if p[IP].dst in MIS_IP:
        return "INPUT   (es para mí)"
    if p[IP].src in MIS_IP:
        return "OUTPUT  (lo genero yo)"
    return "FORWARD (solo me atraviesa)"

casos = [
    IP(src="198.51.100.20", dst="203.0.113.1") / TCP(dport=22),
    IP(src="198.51.100.20", dst="192.168.1.10") / TCP(dport=443),
    IP(src="203.0.113.1", dst="198.51.100.80") / TCP(dport=443),
    IP(src="192.168.1.10", dst="198.51.100.80") / TCP(dport=80),
]
for p in casos:
    print(f"{p[IP].src:>13} -> {p[IP].dst:<14}:{p[TCP].dport:<4}"
          f" {cadena(p)}")
